// Process incoming webhook data from website
const webhookData = $node["Website Webhook Trigger"].json;

console.log('=== WEBSITE WEBHOOK RECEIVED ===');
console.log('Webhook data:', JSON.stringify(webhookData, null, 2));

// Extract company information
const companyInfo = webhookData.companyInfo || {};
const uploadedFiles = webhookData.uploadedFiles || [];
const requestId = webhookData.requestId || `req_${Date.now()}`;

// Generate company ID
const companyId = companyInfo.company_id || `comp_${Date.now()}_${companyInfo.companyName?.replace(/[^a-zA-Z0-9]/g, '_').toLowerCase()}`;

console.log(`Company ID: ${companyId}`);
console.log(`Company Name: ${companyInfo.companyName}`);
console.log(`Files uploaded: ${uploadedFiles.length}`);

// Validate required data
if (!companyInfo.companyName) {
  throw new Error('Company name is required');
}

// Process uploaded files
const processedFiles = uploadedFiles.map((file, index) => {
  console.log(`File ${index + 1}: ${file.name} (${file.size} bytes)`);
  return {
    id: file.id || `file_${Date.now()}_${index}`,
    name: file.name,
    size: file.size,
    type: file.type,
    content: file.content, // Base64 or file path
    uploadPath: file.uploadPath || `/uploads/${companyId}/${file.name}`
  };
});

console.log('=== PROCESSING SUMMARY ===');
console.log(`Request ID: ${requestId}`);
console.log(`Company: ${companyInfo.companyName}`);
console.log(`Files to process: ${processedFiles.length}`);
console.log('===========================');

// Return processed data for next node
return {
  json: {
    // Company information
    company_id: companyId,
    company_name: companyInfo.companyName,
    company_description: companyInfo.description || '',
    contact_email: companyInfo.contactEmail || '',
    contact_phone: companyInfo.contactPhone || '',
    website_url: companyInfo.websiteUrl || '',
    industry: companyInfo.industry || 'Technology',

    // File information
    uploaded_files: processedFiles,
    file_count: processedFiles.length,

    // Request metadata
    request_id: requestId,
    processing_started_at: new Date().toISOString(),
    source: 'website_upload'
  }
};

// Process uploaded files from website
const websiteData = $input.first().json;
const uploadedFiles = websiteData.uploaded_files || [];

console.log('=== PROCESSING UPLOADED FILES ===');
console.log(`Received ${uploadedFiles.length} files from website`);
console.log('Company:', websiteData.company_name);
console.log('Company ID:', websiteData.company_id);

if (uploadedFiles.length === 0) {
  console.error('❌ No uploaded files to process!');
  return {
    json: {
      error: 'No files uploaded',
      company_id: websiteData.company_id,
      company_name: websiteData.company_name
    }
  };
}

// Process uploaded files information
const processedFiles = uploadedFiles.map((file, index) => {
  console.log(`File ${index + 1}: ${file.name} - Size: ${file.size} bytes`);
  return {
    id: file.id,
    name: file.name,
    size: file.size,
    type: file.type,
    content: file.content, // Base64 or file path
    uploadPath: file.uploadPath
  };
});

// Sort files by name for consistent processing order
processedFiles.sort((a, b) => a.name.localeCompare(b.name));

console.log('Files will be processed in this order:');
processedFiles.forEach((file, index) => {
  console.log(`${index + 1}. ${file.name}`);
});

console.log(`Company ID: ${websiteData.company_id}`);
console.log('==============================');

// Return file information for processing
return {
  json: {
    // Consistent company ID throughout workflow
    company_id: websiteData.company_id,
    company_name: websiteData.company_name,
    company_description: websiteData.company_description,
    contact_email: websiteData.contact_email,
    contact_phone: websiteData.contact_phone,
    website_url: websiteData.website_url,
    industry: websiteData.industry,
    // Include all source files for processing
    source_files: processedFiles,
    file_count: processedFiles.length,
    processing_status: 'ready_for_extraction',
    source: 'website_upload'
  }
};

// Prepare uploaded files for content extraction
const fileInfo = $input.first().json;
const sourceFiles = fileInfo.source_files || [];

console.log('=== PREPARING UPLOADED FILES FOR PROCESSING ===');
console.log(`Processing ${sourceFiles.length} uploaded files`);
console.log('Company:', fileInfo.company_name);
console.log('Company ID:', fileInfo.company_id);

if (sourceFiles.length === 0) {
  console.error('❌ No source files to process!');
  return {
    json: {
      error: 'No files uploaded',
      company_id: fileInfo.company_id,
      company_name: fileInfo.company_name
    }
  };
}

// Process ALL files and return them for individual content extraction
const allFilesForProcessing = sourceFiles.map((file, index) => {
  console.log(`Preparing file ${index + 1}/${sourceFiles.length}: ${file.name}`);
  return {
    json: {
      // Consistent company data
      company_id: fileInfo.company_id,
      company_name: fileInfo.company_name,
      company_description: fileInfo.company_description,
      contact_email: fileInfo.contact_email,
      contact_phone: fileInfo.contact_phone,
      website_url: fileInfo.website_url,
      industry: fileInfo.industry,
      // Individual file info for processing
      file_id: file.id,
      file_name: file.name,
      file_size: file.size,
      file_type: file.type,
      file_content: file.content, // Base64 or file path
      upload_path: file.uploadPath,
      file_index: index + 1,
      total_files: sourceFiles.length,
      // Metadata
      all_file_names: sourceFiles.map(f => f.name).join(', '),
      processing_status: 'ready_for_extraction',
      source: 'website_upload'
    }
  };
});

console.log(`✅ Prepared ${allFilesForProcessing.length} files for content extraction`);
console.log('All files will be processed for text extraction');

return allFilesForProcessing;

// Process uploaded file content for text extraction
const fileData = $input.first().json;

console.log('=== PROCESSING UPLOADED FILE CONTENT ===');
console.log(`File: ${fileData.file_name}`);
console.log(`Size: ${fileData.file_size} bytes`);
console.log(`Type: ${fileData.file_type}`);
console.log(`Company: ${fileData.company_name}`);

// Handle different file content types
let fileContent = null;
let processingMethod = 'unknown';

if (fileData.file_content) {
  if (typeof fileData.file_content === 'string') {
    // Base64 encoded content
    if (fileData.file_content.startsWith('data:')) {
      // Data URL format: data:application/pdf;base64,JVBERi0xLjQ...
      const base64Data = fileData.file_content.split(',')[1];
      fileContent = Buffer.from(base64Data, 'base64');
      processingMethod = 'data_url_base64';
    } else if (fileData.file_content.match(/^[A-Za-z0-9+/]+=*$/)) {
      // Pure base64 string
      fileContent = Buffer.from(fileData.file_content, 'base64');
      processingMethod = 'pure_base64';
    } else if (fileData.file_content.startsWith('/') || fileData.file_content.includes('uploads')) {
      // File path - we'll need to read it
      processingMethod = 'file_path';
      fileContent = fileData.file_content; // Keep as path for now
    } else {
      // Direct text content
      fileContent = fileData.file_content;
      processingMethod = 'direct_text';
    }
  } else if (Buffer.isBuffer(fileData.file_content)) {
    // Already a buffer
    fileContent = fileData.file_content;
    processingMethod = 'buffer';
  }
}

console.log(`Processing method: ${processingMethod}`);
console.log(`Content type: ${typeof fileContent}`);

if (!fileContent) {
  console.error('❌ No file content available for processing');
  return {
    json: {
      ...fileData,
      extracted_content: 'ERROR: No file content available',
      extraction_method: 'failed_no_content',
      processing_status: 'failed'
    }
  };
}

// Return file data with content ready for PDF processing
return {
  json: {
    ...fileData,
    file_content_processed: fileContent,
    processing_method: processingMethod,
    processing_status: 'ready_for_pdf_extraction',
    content_available: true
  }
};

// Extract content from current PDF file
const extractedData = $input.first().json;
const fileInfo = $node["Prepare All PDFs for Download"].json;

// Get the full extracted text content
let fullTextContent = '';
let extractionMethod = 'unknown';

if (extractedData && extractedData.data) {
  fullTextContent = extractedData.data;
  extractionMethod = 'text_extraction';
  console.log(`✅ Successfully extracted ${fullTextContent.length} characters from ${fileInfo.file_name}`);
} else {
  if (typeof extractedData === 'string') {
    fullTextContent = extractedData;
    extractionMethod = 'string_conversion';
  } else if (extractedData && typeof extractedData === 'object') {
    for (const [key, value] of Object.entries(extractedData)) {
      if (typeof value === 'string' && value.length > 10) {
        fullTextContent += value + '\n';
        extractionMethod = 'object_scanning';
      }
    }
  }

  if (!fullTextContent) {
    fullTextContent = `PDF extraction failed for ${fileInfo.file_name} - file may be image-based or corrupted`;
    extractionMethod = 'failed';
    console.log(`⚠️ Could not extract text from ${fileInfo.file_name}`);
  }
}

console.log(`File ${fileInfo.file_index}/${fileInfo.total_files}: ${fileInfo.file_name}`);
console.log(`Content length: ${fullTextContent.length} characters`);
console.log(`Extraction method: ${extractionMethod}`);

// Return individual file data with extracted content
return {
  json: {
    company_id: fileInfo.company_id,
    company_name: fileInfo.company_name,
    folder_id: fileInfo.folder_id,
    file_name: fileInfo.file_name,
    file_index: fileInfo.file_index,
    total_files: fileInfo.total_files,
    extracted_content: fullTextContent,
    extraction_method: extractionMethod,
    content_length: fullTextContent.length,
    all_file_names: fileInfo.all_file_names
  }
};

// Collect and merge ALL extracted content from all uploaded files
const allExtractions = $input.all();
const firstFile = allExtractions[0]?.json || {};

console.log('=== MERGING ALL UPLOADED FILE CONTENT ===');
console.log(`Received ${allExtractions.length} extracted files`);
console.log(`Company: ${firstFile.company_name}`);
console.log(`Company ID: ${firstFile.company_id}`);

if (allExtractions.length === 0) {
  console.error('❌ No extracted content received!');
  return {
    json: {
      error: 'No content extracted from uploaded files',
      company_id: firstFile.company_id,
      company_name: firstFile.company_name
    }
  };
}

// Merge all content together
let mergedContent = '';
let totalContentLength = 0;
let successfulExtractions = 0;
let failedExtractions = 0;
const fileDetails = [];

allExtractions.forEach((extraction, index) => {
  const fileData = extraction.json;
  const content = fileData.extracted_content || '';

  console.log(`Processing file ${index + 1}: ${fileData.file_name}`);
  console.log(`  Content length: ${content.length} characters`);
  console.log(`  Extraction method: ${fileData.extraction_method}`);

  if (content && content.length > 50 && !content.includes('extraction failed')) {
    // Add file separator and content
    mergedContent += `\n\n=== CONTENT FROM: ${fileData.file_name} ===\n\n`;
    mergedContent += content;
    mergedContent += `\n\n=== END OF ${fileData.file_name} ===\n\n`;
    successfulExtractions++;
  } else {
    console.log(`  ⚠️ Skipping ${fileData.file_name} - extraction failed or insufficient content`);
    failedExtractions++;
  }

  totalContentLength += content.length;
  fileDetails.push({
    name: fileData.file_name,
    content_length: content.length,
    extraction_method: fileData.extraction_method,
    success: content.length > 50 && !content.includes('extraction failed')
  });
});

// Final data object
const finalData = {
  company_id: firstFile.company_id,
  company_name: firstFile.company_name,
  company_description: firstFile.company_description,
  contact_email: firstFile.contact_email,
  contact_phone: firstFile.contact_phone,
  website_url: firstFile.website_url,
  industry: firstFile.industry,
  content: mergedContent,
  processed_at: new Date().toISOString(),
  source: 'website_upload'
};

// Log results
console.log(`\n=== FINAL MERGE RESULTS ===`);
console.log(`Company ID: ${finalData.company_id}`);
console.log(`Final Company Name: ${finalData.company_name}`);
console.log(`Total files processed: ${allExtractions.length}`);
console.log(`Successful extractions: ${successfulExtractions}`);
console.log(`Failed extractions: ${failedExtractions}`);
console.log(`Total merged content length: ${mergedContent.length} characters`);
console.log(`Files processed: ${fileDetails.map(f => f.name).join(', ')}`);
console.log(`============================\n`);

return { json: finalData };

const report = $input.first().json.response || '';
const dbData = $node['Save Company Data'].json;

console.log(`Report received (Section 1): ${report.substring(0, 100)}...`);
console.log(`Company ID: ${dbData.company_id}`);
console.log(`Company name: ${dbData.company_name}`);
console.log(`Database data content length: ${dbData.content ? dbData.content.length : 'null'}`);

if (!report) {
  console.error('Report generation failed');
  return {
    json: {
      company_id: dbData.company_id,
      company_name: dbData.company_name,
      generated_content: 'Report generation failed',
      content: dbData.content
    }
  };
}

const cleanReport = report
  .replace(/\{\{[^}]*\}\}/g, '[removed-placeholder]')
  .replace(/\$json\.[\w.]+/g, '[removed-variable]')
  .replace(/\$node\[[^\]]+\]\.[\w.\[\]]+/g, '[removed-reference]')
  .replace(/\[date\]/gi, new Date().toLocaleDateString('en-US'))
  .replace(/\[company name\]/gi, dbData.company_name)
  .replace(/\[removed-placeholder\]\s*[,.]?\s*/g, '')
  .replace(/\[removed-variable\]\s*[,.]?\s*/g, '')
  .replace(/\[removed-reference\]\s*[,.]?\s*/g, '')
  .replace(/\s+/g, ' ')
  .trim();

// Validation - check for quality issues
const qualityIssues = [];
if (cleanReport.includes('{{') || cleanReport.includes('}}')) qualityIssues.push('template variables');
if (cleanReport.includes('$json') || cleanReport.includes('$node')) qualityIssues.push('code references');
if (cleanReport.includes('[company]') || cleanReport.includes('undefined')) qualityIssues.push('placeholders');
if (cleanReport.length < 200) qualityIssues.push('too short');
if (/^(.{1,50})\1+/.test(cleanReport)) qualityIssues.push('repetitive content');

if (qualityIssues.length > 0) {
  console.error(`❌ Report quality issues detected: ${qualityIssues.join(', ')}`);
  console.error('Report preview:', cleanReport.substring(0, 200));
}

console.log(`Cleaned Section 1 report: ${cleanReport.substring(0, 100)}...`);
console.log(`Passing company ID: ${dbData.company_id}`);

return {
  json: {
    company_id: dbData.company_id,
    company_name: dbData.company_name,
    generated_content: cleanReport,
    content: dbData.content,
    section_type: 'introduction_engagement_context'
  }
};

// Process feedback from checker or approver and prepare data to send back to Generate Section 1
const inputData = $input.first().json;

// Determine source of feedback
let feedbackSource = 'Unknown';
let feedbackMessage = '';

if (inputData.response && inputData.response.includes('CHECKER_RESULT: FAIL')) {
  feedbackSource = 'Checker';
  feedbackMessage = inputData.response;
} else if (inputData.response && inputData.response.includes('APPROVER_RESULT: REJECT')) {
  feedbackSource = 'Approver';
  feedbackMessage = inputData.response;
}

// ANTI-INFINITE LOOP MECHANISM
const currentRetries = inputData.retry_count || 0;
const maxRetries = 2; // Limit to 2 retries to prevent infinite loops

if (currentRetries >= maxRetries) {
  console.log(`⚠️ LOOP PREVENTION: Section 1 reached maximum retries (${maxRetries}). Auto-approving to continue workflow.`);

  // Auto-approve and send to database to break the loop
  return {
    json: {
      company_id: inputData.company_id,
      company_name: inputData.company_name,
      generated_content: inputData.generated_content || inputData.response || 'Auto-approved after max retries',
      section_complete: true,
      auto_approved: true,
      retry_limit_reached: true,
      approval_timestamp: new Date().toISOString()
    }
  };
}

console.log(`📝 Section 1 feedback from ${feedbackSource}: Content needs revision (Attempt ${currentRetries + 1}/${maxRetries + 1})`);
console.log(`Feedback details: ${feedbackMessage.substring(0, 300)}...`);

// Prepare data to send back to Generate Section 1 with feedback
return {
  json: {
    company_id: inputData.company_id,
    company_name: inputData.company_name,
    content: inputData.content,
    section_type: 'executive_summary_introduction',
    feedback_from: feedbackSource.toLowerCase(),
    quality_feedback: feedbackMessage,
    retry_attempt: true,
    retry_count: currentRetries + 1,
    revision_needed: true
  }
};

// Format approved Section 1 data for database save
const inputData = $input.first().json;

console.log(`✅ Section 1 APPROVED - formatting for database save`);
console.log(`Raw input data keys:`, Object.keys(inputData));
console.log(`Input data:`, JSON.stringify(inputData, null, 2).substring(0, 500));

// Extract the actual data - IF node passes through original data structure
let company_id = inputData.company_id;
let company_name = inputData.company_name;
let generated_content = inputData.generated_content;

// If the data is nested, try to extract it
if (!company_id && inputData.json) {
  company_id = inputData.json.company_id;
  company_name = inputData.json.company_name;
  generated_content = inputData.json.generated_content;
}

console.log(`Extracted data:`);
console.log(`- company_id: ${company_id}`);
console.log(`- company_name: ${company_name}`);
console.log(`- generated_content length: ${generated_content ? generated_content.length : 'missing'}`);

// Ensure all required fields are present
if (!company_id || !company_name || !generated_content) {
  console.error(`❌ Missing required fields for database save after extraction`);
  console.error(`Available data:`, inputData);

  // Try to get from the previous node data that should be available
  const nodeData = $node['Format Section 1 Output']?.json;
  if (nodeData) {
    console.log(`Attempting to use Format Section 1 Output data:`, nodeData);
    company_id = nodeData.company_id || company_id;
    company_name = nodeData.company_name || company_name;
    generated_content = nodeData.generated_content || generated_content;
  }
}

// Return properly formatted data for PostgreSQL
return {
  json: {
    company_id: company_id,
    company_name: company_name,
    generated_content: generated_content,
    section_complete: true,
    approval_timestamp: new Date().toISOString()
  }
};

// Combine source content with previously generated sections for context
const inputData = $input.first().json;
const dbData = $node['Save Company Data'].json;

console.log('=== SECTION 2 CONTEXT PREPARATION ===');
console.log(`Company: ${dbData.company_name}`);
console.log(`Company ID: ${dbData.company_id}`);

// Build context from previously generated sections
let previousContext = '';
const sections = [
  { key: 'introduction_engagement_context', title: 'Section 1: Introduction & Engagement Context' }
];

// Add each completed section to context
sections.forEach(section => {
  if (inputData[section.key] && inputData[section.key].trim()) {
    console.log(`✅ Adding ${section.title} to context`);
    previousContext += `\n\n=== ${section.title.toUpperCase()} ===\n${inputData[section.key]}\n`;
  } else {
    console.log(`⏭️ Skipping ${section.title} (not yet generated)`);
  }
});

if (previousContext.trim()) {
  console.log(`📚 Previous context length: ${previousContext.length} characters`);
} else {
  console.log('📚 No previous sections found - this is the first or second section');
  previousContext = '\n\n=== NO PREVIOUS SECTIONS ===\nThis is among the first sections to be generated for this due diligence report.\n';
}

return {
  json: {
    company_id: dbData.company_id,
    company_name: dbData.company_name,
    content: dbData.content,
    previous_sections_context: previousContext,
    section_type: 'methodology_reliability_levels',
    retry_attempt: inputData.retry_attempt || false,
    quality_feedback: inputData.quality_feedback || '',
    feedback_from: inputData.feedback_from || ''
  }
};

const report = $input.first().json.response || '';
const dbData = $node['Save Company Data'].json;

console.log(`Report received (Section 2): ${report.substring(0, 100)}...`);
console.log(`Company ID: ${dbData.company_id}`);
console.log(`Company name: ${dbData.company_name}`);
console.log(`Database data content length: ${dbData.content ? dbData.content.length : 'null'}`);

if (!report) {
  console.error('Section 2 report generation failed');
  return {
    json: {
      company_id: dbData.company_id,
      company_name: dbData.company_name,
      generated_content: 'Methodology & Reliability report generation failed',
      content: dbData.content
    }
  };
}

const cleanReport = report
  .replace(/\{\{[^}]*\}\}/g, '[removed-placeholder]')
  .replace(/\$json\.[\w.]+/g, '[removed-variable]')
  .replace(/\$node\[[^\]]+\]\.[\w.\[\]]+/g, '[removed-reference]')
  .replace(/\[date\]/gi, new Date().toLocaleDateString('en-US'))
  .replace(/\[company name\]/gi, dbData.company_name)
  .replace(/\[removed-placeholder\]\s*[,.]?\s*/g, '')
  .replace(/\[removed-variable\]\s*[,.]?\s*/g, '')
  .replace(/\[removed-reference\]\s*[,.]?\s*/g, '')
  .replace(/\s+/g, ' ')
  .trim();

// Validation - check for quality issues
const qualityIssues = [];
if (cleanReport.includes('{{') || cleanReport.includes('}}')) qualityIssues.push('template variables');
if (cleanReport.includes('$json') || cleanReport.includes('$node')) qualityIssues.push('code references');
if (cleanReport.includes('[company]') || cleanReport.includes('undefined')) qualityIssues.push('placeholders');
if (cleanReport.length < 200) qualityIssues.push('too short');
if (/^(.{1,50})\1+/.test(cleanReport)) qualityIssues.push('repetitive content');

if (qualityIssues.length > 0) {
  console.error(`❌ Section 2 report quality issues detected: ${qualityIssues.join(', ')}`);
  console.error('Report preview:', cleanReport.substring(0, 200));
}

console.log(`Cleaned Section 2 report: ${cleanReport.substring(0, 100)}...`);
console.log(`Passing company ID: ${dbData.company_id}`);

return {
  json: {
    company_id: dbData.company_id,
    company_name: dbData.company_name,
    generated_content: cleanReport,
    content: dbData.content,
    section_type: 'methodology_reliability_levels'
  }
};

// Process feedback from checker or approver and prepare data to send back to Generate Section 2
const inputData = $input.first().json;

// Determine source of feedback
let feedbackSource = 'Unknown';
let feedbackMessage = '';

if (inputData.response && inputData.response.includes('CHECKER_RESULT: FAIL')) {
  feedbackSource = 'Checker';
  feedbackMessage = inputData.response;
} else if (inputData.response && inputData.response.includes('APPROVER_RESULT: REJECT')) {
  feedbackSource = 'Approver';
  feedbackMessage = inputData.response;
}

console.log(`📝 Section 2 feedback from ${feedbackSource}: Content needs revision`);
console.log(`Feedback details: ${feedbackMessage.substring(0, 300)}...`);

// Prepare data to send back to Generate Section 2 with feedback
return {
  json: {
    company_id: inputData.company_id,
    company_name: inputData.company_name,
    content: inputData.content,
    section_type: 'methodology_reliability_levels',
    feedback_from: feedbackSource.toLowerCase(),
    quality_feedback: feedbackMessage,
    retry_attempt: true,
    revision_needed: true
  }
};

// Format approved Section 2 data for database save
const inputData = $input.first().json;

console.log(`✅ Section 2 APPROVED - formatting for database save`);
console.log(`Company: ${inputData.company_name || 'unknown'}`);
console.log(`Content length: ${inputData.generated_content ? inputData.generated_content.length : 'missing'} characters`);

// Extract the actual data - IF node passes through original data structure
let company_id = inputData.company_id;
let company_name = inputData.company_name;
let generated_content = inputData.generated_content;

// If the data is nested, try to extract it
if (!company_id && inputData.json) {
  company_id = inputData.json.company_id;
  company_name = inputData.json.company_name;
  generated_content = inputData.json.generated_content;
}

console.log(`Extracted data:`);
console.log(`- company_id: ${company_id}`);
console.log(`- company_name: ${company_name}`);
console.log(`- generated_content length: ${generated_content ? generated_content.length : 'missing'}`);

// Ensure all required fields are present
if (!company_id || !company_name || !generated_content) {
  console.error(`❌ Missing required fields for Section 2 database save after extraction`);
  console.error(`Available data:`, inputData);

  // Try to get from the previous node data that should be available
  const nodeData = $node['Format Section 2 Output']?.json;
  if (nodeData) {
    console.log(`Attempting to use Format Section 2 Output data:`, nodeData);
